  const urlApi = globalThis.URL;
  const bytes = blob.size;
  const canCreate =
    bytes > 0 &&
    bytes <= maxPreviewBytes &&
    blob.type.startsWith("image/") &&
    typeof urlApi?.createObjectURL === "function" &&
    typeof urlApi.revokeObjectURL === "function" &&
    current();
