  key?: string,
): OutgoingMediaPreview | undefined {
  return readPreview(usePreviews.getState(), key);
}

export function useOutgoingMediaPreview(
  key?: string,
): OutgoingMediaPreview | undefined {
  return usePreviews((entries) => readPreview(entries, key));
