}

/** Creator text is display data, never markup or a transport filename. */
export function cleanStickerLabel(label: string | undefined): string {
  return (label ?? "")
    .replace(/\s+/gu, " ")
    .replace(new RegExp(UNSAFE_LABEL.source, "gu"), "")
    .trim();
