    packs: fullPacks,
    readPack: async (id) => fullPacks.find((pack) => pack.id === id),
  });
  let fail = true;
  invoke.mockImplementation((cmd: string) => {
    if (cmd === "write_temp_file")
      return Promise.resolve("/tmp/mt-sticker.png");
    if (cmd === "owner_enqueue_file")
